import sys
import os
import json
from decimal import Decimal


def format_amount(val):
    if val is None or val == "":
        return None
    if isinstance(val, (int, float, Decimal)):
        d = Decimal(str(val)) if not isinstance(val, Decimal) else val
        return f"{d:f}"
    return str(val)


def format_date(val):
    if val is None or val == "":
        return None
    val_str = str(val).strip()
    if len(val_str) >= 10 and val_str[4] == "-" and val_str[7] == "-":
        return val_str[:10]
    return val_str


FACT_RULES = {
    "usa.period_3y": {
        "performance start": (
            "usaspending_awards",
            lambda r: (r.get("period_of_performance") or {}).get("start_date"),
            format_date,
        ),
        "performance end": (
            "usaspending_awards",
            lambda r: (r.get("period_of_performance") or {}).get("end_date"),
            format_date,
        ),
    },
    "usa.obligated_95": {
        "amount obligated": (
            "usaspending_awards",
            lambda r: r.get("total_obligation"),
            format_amount,
        ),
        "potential value": (
            "usaspending_awards",
            lambda r: r.get("base_and_all_options"),
            format_amount,
        ),
    },
}


def load_awards(packet_dir):
    awards_path = os.path.join(packet_dir, "usaspending_awards.json")
    if not os.path.exists(awards_path):
        for fname in os.listdir(packet_dir):
            if fname.lower() == "usaspending_awards.json":
                awards_path = os.path.join(packet_dir, fname)
                break

    if not os.path.exists(awards_path):
        return {}

    with open(awards_path, "r", encoding="utf-8") as f:
        records = json.load(f, parse_float=Decimal, parse_int=Decimal)

    entity_records = {}
    for record in records:
        award_id = record.get("generated_unique_award_id")
        if award_id:
            entity_records.setdefault(award_id, []).append(record)
    return entity_records


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    entity_records = load_awards(packet_dir)

    pairs = manifest.get("pairs", [])
    manifest_facts = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        if "::" not in pair:
            continue
        rule_id, entity = pair.split("::", 1)

        rule_fact_names = manifest_facts.get(rule_id)
        if rule_fact_names is None:
            rule_fact_names = list(FACT_RULES.get(rule_id, {}).keys())

        pair_result = {}
        records = entity_records.get(entity, [])

        for fact_name in rule_fact_names:
            extractor_info = FACT_RULES.get(rule_id, {}).get(fact_name)
            if not extractor_info:
                pair_result[fact_name] = "ABSENT"
                continue

            doc_name, getter, formatter = extractor_info

            values_seen = set()
            for r in records:
                raw_val = getter(r)
                formatted_val = formatter(raw_val)
                if formatted_val is not None:
                    values_seen.add(formatted_val)

            if not values_seen:
                pair_result[fact_name] = "ABSENT"
            elif len(values_seen) == 1:
                val = next(iter(values_seen))
                pair_result[fact_name] = [val, doc_name]
            else:
                pair_result[fact_name] = "CONFLICT"

        output[pair] = pair_result

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()

