import sys
import json
import re
from pathlib import Path
from decimal import Decimal

def format_date(val):
    if val is None:
        return None
    val_str = str(val).strip()
    m = re.match(r'^(\d{4}-\d{2}-\d{2})', val_str)
    if m:
        return m.group(1)
    return val_str

def extract_fact_value(rec, fact_name):
    if fact_name == "performance start":
        pop = rec.get("period_of_performance") or {}
        val = pop.get("start_date")
        if val is None:
            return None, "date"
        return format_date(val), "date"
    elif fact_name == "performance end":
        pop = rec.get("period_of_performance") or {}
        val = pop.get("end_date")
        if val is None:
            return None, "date"
        return format_date(val), "date"
    elif fact_name == "amount obligated":
        val = rec.get("total_obligation")
        if val is None:
            return None, "amount"
        return val, "amount"
    elif fact_name == "potential value":
        val = rec.get("base_and_all_options")
        if val is None:
            return None, "amount"
        return val, "amount"
    return None, "unknown"

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = Path(sys.argv[1])
    manifest_path = Path(sys.argv[2])

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    awards_file = packet_dir / "usaspending_awards.json"
    awards_by_id = {}
    if awards_file.exists():
        with open(awards_file, "r", encoding="utf-8") as f:
            awards_data = json.load(f, parse_float=Decimal, parse_int=Decimal)
            if isinstance(awards_data, list):
                for rec in awards_data:
                    award_id = rec.get("generated_unique_award_id")
                    if award_id:
                        awards_by_id.setdefault(award_id, []).append(rec)

    manifest_facts = manifest.get("facts", {})
    pairs = manifest.get("pairs", [])
    output = {}

    for pair in pairs:
        if "::" in pair:
            rule_id, entity_id = pair.split("::", 1)
        else:
            rule_id, entity_id = pair, ""

        facts_list = manifest_facts.get(rule_id, [])
        pair_result = {}
        records = awards_by_id.get(entity_id, [])

        for fact_name in facts_list:
            values = []
            val_type = "unknown"
            for rec in records:
                v, t = extract_fact_value(rec, fact_name)
                val_type = t
                if v is not None:
                    values.append(v)

            if not values:
                pair_result[fact_name] = "ABSENT"
            else:
                if val_type == "amount":
                    first_val = values[0]
                    if all(v == first_val for v in values):
                        pair_result[fact_name] = [str(first_val), "usaspending_awards"]
                    else:
                        pair_result[fact_name] = "CONFLICT"
                else:
                    first_val = values[0]
                    if all(v == first_val for v in values):
                        pair_result[fact_name] = [str(first_val), "usaspending_awards"]
                    else:
                        pair_result[fact_name] = "CONFLICT"

        output[pair] = pair_result

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()

