import sys
import os
import json
from decimal import Decimal

FACT_RULES = {
    "performance start": ("usaspending_awards", ["period_of_performance", "start_date"], "date"),
    "performance end": ("usaspending_awards", ["period_of_performance", "end_date"], "date"),
    "amount obligated": ("usaspending_awards", ["total_obligation"], "amount"),
    "potential value": ("usaspending_awards", ["base_and_all_options"], "amount"),
}

def get_nested(d, path):
    curr = d
    for p in path:
        if isinstance(curr, dict) and p in curr:
            curr = curr[p]
        else:
            return None
    return curr

def normalize_date(val):
    if val is None:
        return None
    val_str = str(val).strip()
    if not val_str:
        return None
    if len(val_str) >= 10 and val_str[4] == '-' and val_str[7] == '-':
        return val_str[:10]
    return val_str

def normalize_amount(val):
    if val is None:
        return None
    if isinstance(val, str):
        val = val.strip()
        if not val:
            return None
        val = Decimal(val)
    if isinstance(val, (int, float, Decimal)):
        d = Decimal(str(val))
        return format(d, 'f')
    return None

def main():
    if len(sys.argv) < 3:
        return

    packet_dir = sys.argv[1]
    manifest_file = sys.argv[2]

    with open(manifest_file, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    awards_file = os.path.join(packet_dir, "usaspending_awards.json")
    if not os.path.exists(awards_file):
        for root, _, files in os.walk(packet_dir):
            for file in files:
                if file == "usaspending_awards.json":
                    awards_file = os.path.join(root, file)
                    break
            if os.path.exists(awards_file):
                break

    awards_data = []
    if os.path.exists(awards_file):
        with open(awards_file, 'r', encoding='utf-8') as f:
            awards_data = json.load(f, parse_float=Decimal, parse_int=Decimal)

    awards_by_id = {}
    if isinstance(awards_data, list):
        for item in awards_data:
            if isinstance(item, dict):
                aid = item.get("generated_unique_award_id")
                if aid is not None:
                    aid_str = str(aid).strip()
                    awards_by_id.setdefault(aid_str, []).append(item)

    pairs = manifest.get("pairs", [])
    rules_facts = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        if "::" not in pair:
            continue
        rule_id, entity_id = pair.split("::", 1)
        facts = rules_facts.get(rule_id, [])

        records = awards_by_id.get(entity_id.strip(), [])
        pair_result = {}

        for fact in facts:
            if fact not in FACT_RULES:
                pair_result[fact] = "ABSENT"
                continue

            doc_name, path, val_type = FACT_RULES[fact]
            extracted_values = []

            for record in records:
                raw_val = get_nested(record, path)
                if val_type == "date":
                    norm_val = normalize_date(raw_val)
                elif val_type == "amount":
                    norm_val = normalize_amount(raw_val)
                else:
                    norm_val = str(raw_val) if raw_val is not None else None

                if norm_val is not None:
                    extracted_values.append(norm_val)

            if not extracted_values:
                pair_result[fact] = "ABSENT"
            else:
                distinct_values = list(dict.fromkeys(extracted_values))
                if len(distinct_values) == 1:
                    pair_result[fact] = [distinct_values[0], doc_name]
                else:
                    pair_result[fact] = "CONFLICT"

        output[pair] = pair_result

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()

