import json
import os
import re
import sys
from decimal import Decimal

FACT_CONFIG = {
    "performance start": {
        "doc": "usaspending_awards",
        "field": "period_of_performance.start_date",
        "type": "date",
    },
    "performance end": {
        "doc": "usaspending_awards",
        "field": "period_of_performance.end_date",
        "type": "date",
    },
    "amount obligated": {
        "doc": "usaspending_awards",
        "field": "total_obligation",
        "type": "amount",
    },
    "potential value": {
        "doc": "usaspending_awards",
        "field": "base_and_all_options",
        "type": "amount",
    },
}


def get_field_value(record, path):
    parts = path.split(".")
    curr = record
    for p in parts:
        if isinstance(curr, dict):
            curr = curr.get(p)
        else:
            return None
    return curr


def normalize_date(val):
    if val is None:
        return None
    s = str(val).strip()
    if not s or s.lower() == "null":
        return None
    m = re.match(r"^(\d{4}-\d{2}-\d{2})", s)
    if m:
        return m.group(1)
    return s


def normalize_amount(val):
    if val is None:
        return None
    s = str(val).strip().replace("$", "").replace(",", "")
    if not s or s.lower() == "null":
        return None
    try:
        d = Decimal(s)
        formatted = format(d, "f")
        return d, formatted
    except Exception:
        return None


def load_documents(packet_dir):
    docs = {}
    target_docs = {"usaspending_awards"}

    if not os.path.exists(packet_dir):
        return docs

    for fname in os.listdir(packet_dir):
        stem, ext = os.path.splitext(fname)
        if ext.lower() == ".json" and stem in target_docs:
            fpath = os.path.join(packet_dir, fname)
            try:
                with open(fpath, "r", encoding="utf-8") as f:
                    data = json.load(f, parse_float=str, parse_int=str)
                records = []
                if isinstance(data, list):
                    records = data
                elif isinstance(data, dict):
                    for k in ["awards", "results", "data"]:
                        if k in data and isinstance(data[k], list):
                            records = data[k]
                            break
                    else:
                        records = [data]

                by_id = {}
                for rec in records:
                    if not isinstance(rec, dict):
                        continue
                    keys = set()
                    gid = rec.get("generated_unique_award_id")
                    if gid:
                        keys.add(str(gid))
                    aid = rec.get("id")
                    if aid is not None:
                        keys.add(str(aid))

                    for key in keys:
                        by_id.setdefault(key, []).append(rec)

                docs[stem] = by_id
            except Exception:
                pass

    return docs


def resolve_fact(records, config):
    doc_name = config["doc"]
    field = config["field"]
    ftype = config["type"]

    extracted = []
    for rec in records:
        val = get_field_value(rec, field)
        if val is None:
            continue
        if ftype == "date":
            norm = normalize_date(val)
            if norm is not None:
                extracted.append(norm)
        elif ftype == "amount":
            norm = normalize_amount(val)
            if norm is not None:
                extracted.append(norm)

    if not extracted:
        return "ABSENT"

    if ftype == "date":
        unique_dates = set(extracted)
        if len(unique_dates) > 1:
            return "CONFLICT"
        return [extracted[0], doc_name]

    elif ftype == "amount":
        unique_decimals = {item[0] for item in extracted}
        if len(unique_decimals) > 1:
            return "CONFLICT"
        return [extracted[0][1], doc_name]

    return "ABSENT"


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    pairs = manifest.get("pairs", [])
    facts_spec = manifest.get("facts", {})

    docs = load_documents(packet_dir)

    output = {}

    for pair in pairs:
        if "::" not in pair:
            continue
        rule_id, entity = pair.split("::", 1)
        facts_list = facts_spec.get(rule_id, [])

        pair_result = {}
        for fact_name in facts_list:
            config = FACT_CONFIG.get(fact_name)
            if not config:
                pair_result[fact_name] = "ABSENT"
                continue

            doc_name = config["doc"]
            doc_data = docs.get(doc_name, {})
            records = doc_data.get(entity, [])

            if not records:
                pair_result[fact_name] = "ABSENT"
            else:
                pair_result[fact_name] = resolve_fact(records, config)

        output[pair] = pair_result

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()

