from pathlib import Path
from decimal import Decimal


def get_nested(data, keys):
    curr = data
    for k in keys:
        if not isinstance(curr, dict):
            return None
        curr = curr.get(k)
    return curr


def normalize_val(val, val_type):
    if val is None:
        return None
    if val_type == "date":
        if not isinstance(val, str):
            return None
        s = val.strip()
        if not s:
            return None
        # Extract YYYY-MM-DD
        date_part = s.split()[0].split("T")[0]
        return date_part
    elif val_type == "amount":
        if isinstance(val, (Decimal, int, float)):
            return Decimal(str(val))
        if isinstance(val, str):
            s = val.strip()
            if not s:
                return None
            try:
                return Decimal(s)
            except Exception:
                return None
        return None
    return val


FACT_RULES = {
    "usa.period_3y": {
        "performance start": {
            "doc": "usaspending_awards",
            "extractor": lambda r: get_nested(r, ["period_of_performance", "start_date"]),
            "type": "date",
        },
        "performance end": {
            "doc": "usaspending_awards",
            "extractor": lambda r: get_nested(r, ["period_of_performance", "end_date"]),
            "type": "date",
        },
    },
    "usa.obligated_95": {
        "amount obligated": {
            "doc": "usaspending_awards",
            "extractor": lambda r: get_nested(r, ["total_obligation"]),
            "type": "amount",
        },
        "potential value": {
            "doc": "usaspending_awards",
            "extractor": lambda r: get_nested(r, ["base_and_all_options"]),
            "type": "amount",
        },
    },
}


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = Path(sys.argv[1])
    manifest_file = Path(sys.argv[2])

    with open(manifest_file, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    # Load awards
    awards_file = packet_dir / "usaspending_awards.json"
    awards_by_id = {}
    if awards_file.exists():
        with open(awards_file, "r", encoding="utf-8") as f:
            awards_data = json.load(f, parse_float=Decimal, parse_int=Decimal)
        if isinstance(awards_data, list):
            for award in awards_data:
                award_id = award.get("generated_unique_award_id")
                if award_id:
                    awards_by_id.setdefault(award_id, []).append(award)

    result = {}
    pairs = manifest.get("pairs", [])
    facts_config = manifest.get("facts", {})

    for pair in pairs:
        if "::" not in pair:
            continue
        rule_id, entity_id = pair.split("::", 1)
        facts_list = facts_config.get(rule_id, [])

        pair_result = {}
        records = awards_by_id.get(entity_id, [])

        rule_facts = FACT_RULES.get(rule_id, {})

        for fact_name in facts_list:
            fact_def = rule_facts.get(fact_name)
            if not fact_def:
                pair_result[fact_name] = "ABSENT"
                continue

            doc_name = fact_def["doc"]
            extractor = fact_def["extractor"]
            val_type = fact_def["type"]

            extracted_values = []
            for record in records:
                raw_val = extractor(record)
                norm_val = normalize_val(raw_val, val_type)
                if norm_val is not None:
                    extracted_values.append(norm_val)

            if not extracted_values:
                pair_result[fact_name] = "ABSENT"
            else:
                # Check for distinct values
                distinct = []
                for v in extracted_values:
                    if not any(v == d for d in distinct):
                        distinct.append(v)

                if len(distinct) > 1:
                    pair_result[fact_name] = "CONFLICT"
                else:
                    final_val = distinct[0]
                    formatted_val = str(final_val)
                    pair_result[fact_name] = [formatted_val, doc_name]

        result[pair] = pair_result

    print(json.dumps(result, indent=1))


if __name__ == "__main__":
    main()

